    ctx.beginPath(); ctx.moveTo(x+cut,y); ctx.lineTo(right-cut,y); ctx.lineTo(right,y+cut);
    ctx.lineTo(right,end-cut); ctx.lineTo(right-cut,end); ctx.lineTo(x+cut,end);
    ctx.lineTo(x,end-cut); ctx.lineTo(x,y+cut); ctx.closePath(); ctx.fill();
    ctx.fillStyle='rgba(169,169,192,.32)';
    for (let n=1;n<13;n++) ctx.fillRect(x+2,y+(end-y)*n/13,right-x-4,.58);
    ctx.fillStyle='#9b8c86';
