  for (const u of [.375,.625]) ctx.fillRect(u-.003,0,.006,1);
  for (const v of [.365,.59]) ctx.fillRect(0,1-v-.004,1,.008);
  ctx.fillRect(0,0,.213,1); ctx.fillRect(.787,0,.213,1);
  ctx.fillStyle=finish ? 'rgb(255,72,152)' : '#6b6765';
  for (const u of [.214,.785]) ctx.fillRect(u,0,.002,1);
  ctx.restore();
